1	import ContentCopyOutlined from '@mui/icons-material/ContentCopyOutlined'
2	import { IconButton, Tooltip } from '@mui/material'
3	import { copyTextToClipboard } from '../../../../services/clipboard_text'
4	import { dialogService } from '../../../../services/dialog_service'
5	
6	interface ActionConversationCopyButtonProps {
7	    label: string
8	    text: string
9	}
10	
11	/** Copies one transcript item's source representation. */
12	export function ActionConversationCopyButton({ label, text }: ActionConversationCopyButtonProps) {
13	    const handleCopy = async () => {
14	        try {
15	            await copyTextToClipboard(text)
16	        } catch (error) {
17	            dialogService.error(error, { fallbackMessage: 'Could not copy conversation item' })
18	        }
19	    }
20	
21	    return (
22	        <Tooltip title={label}>
23	            <IconButton aria-label={label} onClick={handleCopy} size="small" sx={{ height: 28, width: 28 }}>
24	                <ContentCopyOutlined sx={{ fontSize: 16 }} />
25	            </IconButton>
26	        </Tooltip>
27	    )
28	}
