1	import type { ActionConversationRenderGroup } from './action_conversation_render_groups'
2	import type { ActionConversationChatlogTracker } from './action_conversation_chatlog_tracker'
3	import { ActionConversationEventRow } from '../events/action_conversation_event_row'
4	import { ActionConversationMessage } from '../messages/action_conversation_message'
5	import { SubAgentGroup } from '../events/sub_agent_group'
6	import { TerminalToolCallGroup } from '../events/terminal_tool_call_group'
7	import type { ActionConversationCommandOperations } from '../state/action_conversation_command_service'
8	
9	interface ActionConversationGroupListProps {
10	    commands: ActionConversationCommandOperations
11	    groups: ActionConversationRenderGroup[]
12	    tracker: ActionConversationChatlogTracker
13	}
14	
15	/** Maps stable conversation render groups to their leaf components. */
16	export function ActionConversationGroupList({ commands, groups, tracker }: ActionConversationGroupListProps) {
17	    return groups.map((group) => {
18	        if (group.kind === 'terminalToolCalls') {
19	            return (
20	                <TerminalToolCallGroup
21	                    entries={group.entries}
22	                    groupKey={group.key}
23	                    key={group.key}
24	                    tracker={tracker}
25	                />
26	            )
27	        }
28	        if (group.kind === 'subAgent') {
29	            return (
30	                <SubAgentGroup
31	                    entry={group.entry}
32	                    groupKey={group.key}
33	                    groups={group.groups}
34	                    key={group.key}
35	                    label={group.label}
36	                    tracker={tracker}
37	                    runningCount={group.runningCount}
38	                />
39	            )
40	        }
41	
42	        const { entry } = group
43	        if (entry.kind === 'message') {
44	            return <ActionConversationMessage commands={commands} entry={entry} key={group.key} tracker={tracker} />
45	        }
46	
47	        return <ActionConversationEventRow entry={entry} grouped={false} key={group.key} />
48	    })
49	}
